<?php use CmuLms\View; $title='Users'; include __DIR__.'/../layout/header.php'; $q=$_GET['q']??''; $role_filter=$role_filter??'all'; $page=(int)($page??1); $pages=(int)($pages??1); $per_page=(int)($per_page??20); ?>
<section class="card"><h1>User management</h1>
<details><summary>Import students from CSV</summary><form method="post" action="?route=admin-student-import" enctype="multipart/form-data" class="grid"><?=View::csrfField()?><label>CSV file<input type="file" name="file" accept=".csv,text/csv" required></label><label>Enroll into course (optional)<select name="course_id"><option value="0">Do not enroll yet</option><?php foreach(($courses??[]) as $course): ?><option value="<?=View::e($course['id'])?>"><?=View::e($course['code'])?> · <?=View::e($course['title'])?></option><?php endforeach; ?></select></label><button>Import students</button></form><p class="muted">Accepted columns: id_number (or school_id), full_name, or first_name, middle_initial, last_name, plus section_code, year_level, and course. New accounts use <strong>ChangeMe!</strong> and must change it after login.</p></details>
<details><summary>Create user</summary><form method="post" action="?route=admin-user-create" class="grid"><?=View::csrfField()?><label>School ID<input name="id_number" required></label><label>Full name<input name="name" required></label><label>First name<input name="first_name"></label><label>Middle initial<input name="middle_initial"></label><label>Last name<input name="last_name"></label><label>Email<input type="email" name="email"></label><label>Role<select name="role"><option value="student">Student</option><option value="teacher">Teacher</option><option value="admin">Admin</option></select></label><label>Section<input name="section_code"></label><label>Year level<input name="year_level"></label><label>Course<input name="course"></label><button>Create with default password</button></form><p class="muted">New accounts use the temporary password <strong>ChangeMe!</strong>.</p></details>
<form method="get" class="grid"><input type="hidden" name="route" value="admin-users"><label>Search<input name="q" placeholder="Name, school ID, section, course" value="<?=View::e($q)?>"></label><label>Role<select name="role"><option value="all" <?=$role_filter==='all'?'selected':''?>>All roles</option><option value="student" <?=$role_filter==='student'?'selected':''?>>Students</option><option value="teacher" <?=$role_filter==='teacher'?'selected':''?>>Teachers</option><option value="admin" <?=$role_filter==='admin'?'selected':''?>>Admins</option></select></label><label>Rows<select name="per_page"><option value="10" <?=$per_page===10?'selected':''?>>10</option><option value="20" <?=$per_page===20?'selected':''?>>20</option><option value="50" <?=$per_page===50?'selected':''?>>50</option><option value="100" <?=$per_page===100?'selected':''?>>100</option></select></label><button>Filter</button></form>
<p>Showing page <?=View::e($page)?> of <?=View::e($pages)?> · <?=View::e($total??0)?> accounts</p>
<div style="overflow-x:auto"><table><thead><tr><th>Name</th><th>School ID</th><th>Role</th><th>Section</th><th>Status</th><th>Lock</th><th>Action</th></tr></thead><tbody><?php foreach(($students??[]) as $s): $disabled=!empty($s['disabled_at']); $locked=!empty($s['locked_until'])&&strtotime($s['locked_until'])>time(); ?><tr><td><?=View::e($s['name'])?></td><td><?=View::e($s['id_number'])?></td><td><?=View::e($s['role'])?></td><td><?=View::e($s['section_code'])?></td><td><span class="badge"><?=$disabled?'Disabled':'Active'?></span></td><td><?=$locked?'Until '.View::e($s['locked_until']):'Not locked'?></td><td><form method="post" action="?route=admin-toggle" style="display:inline" onsubmit="return confirm('Are you sure you want to <?=$disabled?'enable':'disable'?> <?=View::e($s['name'])?> (<?=View::e($s['id_number'])?>)?')"><?=View::csrfField()?><input type="hidden" name="user_id" value="<?=View::e($s['id'])?>"><input type="hidden" name="state" value="<?=$disabled?'enable':'disable'?>"><button><?=$disabled?'Enable':'Disable'?></button></form><?php if($locked): ?><form method="post" action="?route=admin-unlock" style="display:inline" onsubmit="return confirm('Unlock <?=View::e($s['name'])?> (<?=View::e($s['id_number'])?>)?')"><?=View::csrfField()?><input type="hidden" name="user_id" value="<?=View::e($s['id'])?>"><button>Unlock</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(empty($students)): ?><tr><td colspan="7">No matching accounts.</td></tr><?php endif; ?></tbody></table></div>
<p><?php if($page>1): ?><a class="btn" href="?route=admin-users&amp;q=<?=urlencode($q)?>&amp;role=<?=urlencode($role_filter)?>&amp;per_page=<?=$per_page?>&amp;page=<?=$page-1?>">Previous</a><?php endif; ?> Page <?=View::e($page)?> of <?=View::e($pages)?> <?php if($page<$pages): ?><a class="btn" href="?route=admin-users&amp;q=<?=urlencode($q)?>&amp;role=<?=urlencode($role_filter)?>&amp;per_page=<?=$per_page?>&amp;page=<?=$page+1?>">Next</a><?php endif; ?></p></section>
<?php include __DIR__.'/../layout/footer.php'; ?>
